public static int maxRegions(int N) {
    // Base case:
    if (N == 0) {
        return 2;
    }

    // Recursive case:
    int result = 0;
    for (int i = 1; i <= Math.floor(Math.sqrt(N)); i++) {
        result = Math.max(result, maxRegions(N - i * i));
    }
    return result + 1;
}

