public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Check if the starting and ending n-intersections are valid
  if (start[0] >= n || start[1] >= n || end[0] >= n || end[1] >= n) {
    return "cannot be travelled";
  }

  // Check if the starting n-intersection is the same as the ending n-intersection
  if (start[0] == end[0] && start[1] == end[1]) {
    return "can be travelled";
  }

  // Check if the starting n-intersection is a valid starting point
  if (!isValidStartingPoint(start, paths)) {
    return "cannot be travelled";
  }

  // Check if the ending n-intersection is a valid ending point
  if (!isValidEndingPoint(end, paths)) {
    return "cannot be travelled";
  }

  // Check if the n-teresting space is reachable from the starting n-intersection
  boolean[][] visited = new boolean[n][n];
  Queue<int[]> queue = new LinkedList<>();
  queue.offer(start);
  visited[start[0]][start[1]] = true;
  while (!queue.isEmpty()) {
    int[] current = queue.poll();
    for (int[] direction : paths[current[0]][current[1]]) {
      int nextRow = current[0] + direction[0];
      int nextCol = current[1] + direction[1];
      if (nextRow < 0 || nextRow >= n || nextCol < 0 || nextCol >= n) {
        continue;
      }
      if (visited[nextRow][nextCol]) {
        continue;
      }
      visited[nextRow][nextCol] = true;
      if (nextRow == end[0] && nextCol == end[1]) {
        return "can be travelled";
      }
      queue.offer(new int[] {nextRow, nextCol});
    }
  }

  return "cannot be travelled";
}

