int current = stack[top--];

if (current == end[0] * n + end[1]) {
return "can be travelled";
}

for (int[] path : paths) {
int currentRow = current / n;
int currentCol = current % n;
int row = currentRow + path[0];
int col = currentCol + path[1];

if (row >= n || col >= n || row < 0 || col < 0) {
continue;
}

int index = row * n + col;

if (!visited[index]) {
visited[index] = true;
stack[++top] = index;
