public int[] twoSum(int[] nums, int target) {
    Set<Integer> seen = new HashSet<>();
    int[] result = new int[2];
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (seen.contains(complement)) {
            result[0] = seen.get(complement);
            result[1] = i;
            break;
        } else {
            seen.add(nums[i]);
        }
    }
    return result;
}

