public double trimMean(int[] arr) {
    // Calculate the number of elements to be removed from the smallest and largest 5%
    int numElementsToRemove = (int)((arr.length * 5) / 100);

    // Remove the smallest 5% of elements
    int[] sortedArr = Arrays.copyOf(arr, arr.length);
    Arrays.sort(sortedArr);
    for (int i = 0; i < numElementsToRemove; i++) {
        sortedArr[i] = 0;
    }

    // Remove the largest 5% of elements
    Arrays.sort(sortedArr, Collections.reverseOrder());
    for (int i = 0; i < numElementsToRemove; i++) {
        sortedArr[i] = 0;
    }

    // Calculate the mean of the remaining elements
    double mean = 0;
    for (int i = 0; i < sortedArr.length; i++) {
        mean += sortedArr[i];
    }
    mean /= sortedArr.length;

    // Return the mean with an error within 10^-5
    return mean - (mean * 10e-5);
}

public double trimMean(int[] arr) {
    // Sort the array in ascending order
    Arrays.sort(arr);

    // Find the 5% percentile indexes
    int minIndex = (int) (arr.length * 0.05);
    int maxIndex = arr.length - (int) (arr.length * 0.05);

    // Calculate the mean of the remaining elements
    double mean = 0;
    for (int i = minIndex; i <= maxIndex; i++) {
        mean += arr[i];
    }
    mean /= (arr.length - (minIndex - maxIndex));

    // Return the trimmed mean
    return mean;
}

