    int smallest = (int) (arr.length * 0.05);
    int largest = arr.length - smallest;

    // Sort the array and remove the smallest and largest elements
    Arrays.sort(arr);
    int[] trimmed = Arrays.copyOfRange(arr, smallest, largest);

    // Calculate the mean
    double mean = Statistics.mean(trimmed);

    // Return the mean with an error within 10^-5
    return Math.round(mean * 100000) / 100000;
  }

