    int numToRemove = (int)(arr.length * 0.05);
    // Remove the smallest elements
    double[] trimmed = new double[(arr.length - numToRemove)];
    for (int i = 0; i < numToRemove; i++) {
        trimmed[i] = arr[i];
    }
    // Remove the largest elements
    for (int i = arr.length - 1; i >= arr.length - numToRemove; i--) {
        trimmed[i] = arr[i];
