}

public boolean canArrange(int[] arr, int k) {
//Check if the input array is of size 0 or 1, if so, return false.
if (arr.length <= 1) {
return false;
}

//Initialize the sum variable to 0
int sum = 0;

//Loop through the array and calculate the sum of all elements
for (int i = 0; i < arr.length; i++) {
sum += arr[i];
}

//If the sum is not divisible by k, return false
if (sum % k != 0) {
return false;
}

//If the sum is divisible by k, check if the length of the array is odd
if (arr.length % 2 != 0) {
//If the length is odd, check if the sum is divisible by k
if (sum % k != 0) {
return false;
}
} else {
//If the length is even, check if the sum is divisible by 2k
if (sum % (2 * k) != 0) {
return false;
}
}

//If the above checks are successful, return true
return true;
}

public boolean canArrange(int[] arr, int k) {
    // Check if the input array is null or has odd length
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }

    // Initialize a hash map to store the sums of pairs
    Map<Integer, Integer> pairSums = new HashMap<>();

    // Loop through the array and calculate the sums of pairs
    for (int i = 0; i < arr.length; i += 2) {
        int sum = arr[i] + arr[i + 1];
        pairSums.put(sum, pairSums.getOrDefault(sum, 0) + 1);
    }

    // Check if any pair sum is divisible by k
    for (int sum : pairSums.keySet()) {
        if (sum % k == 0) {
            return true;
        }
    }

    // If no pair sum is divisible by k, return false
    return false;
}

public boolean canArrange(int[] arr, int k) {
    // Check if k is a divisor of the sum of the array
    if (k > 0 && arr.length > 0 && (arr.length % 2 == 0)) {
        int sum = 0;
        for (int num : arr) {
            sum += num;
        }
        if (sum % k == 0) {
            // Calculate the number of pairs
            int numPairs = arr.length / 2;
            // Initialize the hash table
            Map<Integer, Boolean> rems = new HashMap<>();
            for (int i = 0; i < numPairs; i++) {
                rems.put(i, false);
            }
            // Check if each pair satisfies the condition
            for (int i = 0; i < numPairs; i++) {
                int rem = (sum / k) % numPairs;
                if (rems.containsKey(rem) && !rems.get(rem)) {
                    rems.put(rem, true);
                } else {
                    return false;
                }
            }
            return true;
        }
    }
    return false;
}

