    int[] pairs = new int[n/2];
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            pairs[i] = arr[i] + arr[j];
            if (pairs[i] % k == 0) {
                return true;
            }
        }
    }
    return false;
}

