   if (arr.length % 2 == 1 || k <= 1) {
       return false;
   }

   int n = arr.length;
   int half = n / 2;
   int[] sums = new int[half];

   for (int i = 0; i < half; i++) {
       sums[i] = 0;
   }

   for (int i = 0; i < n; i++) {
       sums[i % half] += arr[i];
   }

   for (int i = 0; i < half; i++) {
       if (sums[i] % k != 0) {
           return false;
       }
   }

   return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a queue to store the nodes we need to visit
    Queue<Integer> queue = new LinkedList<>();
    // Create a hash set to keep track of the nodes we have visited
    Set<Integer> visited = new HashSet<>();
    // Create a hash set to keep track of the apples we have collected
    Set<Integer> apples = new HashSet<>();
    // Create a hash map to keep track of the nodes and their neighbors
    Map<Integer, List<Integer>> neighbors = new HashMap<>();
    // Initialize the queue with the starting node
    queue.add(0);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int current = queue.remove();
        // Mark the current node as visited
        visited.add(current);
        // If the current node has an apple, add it to the set of apples
        if (hasApple[current]) {
            apples.add(current);
        }
        // Loop through the neighbors of the current node
        for (int neighbor : neighbors.get(current)) {
            // If the neighbor has not been visited, add it to the queue
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
            }
        }
    }
    // Return the minimum time required to collect all the apples and return to the starting node
    return apples.size();
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {

    // Initialize the queue with the starting node
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    int currentTime = 0;
    int totalTime = 0;

    // Loop through all nodes in the graph
    while (!queue.isEmpty()) {

        // Get the current node and its neighbors
        int node = queue.poll();
        int[] neighbors = edges[node];

        // Increment the current time
        currentTime++;

        // Iterate over the neighbors
        for (int neighbor : neighbors) {

            // If the neighbor has an apple, add it to the queue
            if (hasApple[neighbor]) {
                queue.add(neighbor);
            }

            // Update the total time spent in the graph
            totalTime += currentTime;
        }
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a boolean array to indicate if a node has been visited
    boolean[] visited = new boolean[n];

    // Initialize a queue to store the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();

    // Add node 0 to the queue
    queue.add(0);

    // Initialize a variable to keep track of the time
    int time = 0;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the size of the queue
        int size = queue.size();

        // Loop through the nodes in the queue
        for (int i = 0; i < size; i++) {
            // Get the node from the queue
            int node = queue.poll();

            // If the node has an apple and has not been visited before, add it to the list of apples and mark it as visited
            if (hasApple[node] && !visited[node]) {
                visited[node] = true;
                // Increment the time by 1
                time++;
            }

            // Add the neighbors of the node to the queue
            for (int neighbor : edges[node]) {
                if (!visited[neighbor]) {
                    queue.add(neighbor);
                }
            }
        }
    }

    // Return the time
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a graph from the edge list
    Graph graph = new Graph(n);
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }

    // Perform BFS to find the shortest path from the start node to all other nodes
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int[] distance = new int[n];
    Arrays.fill(distance, -1);
    queue.offer(0);
    visited[0] = true;
    distance[0] = 0;

    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph.getNeighbors(node)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                distance[neighbor] = distance[node] + 1;
                queue.offer(neighbor);
            }
        }
    }

    // Find the minimum time required to collect all apples
    int time = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            time = Math.max(time, distance[i]);
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a map to store the neighbors of each node and their corresponding weights
    Map<Integer, List<Integer>> neighbors = new HashMap<>();
    for (int[] edge : edges) {
        int src = edge[0];
        int dst = edge[1];
        int weight = 1; // default weight is 1
        if (neighbors.containsKey(src)) {
            neighbors.get(src).add(dst);
        } else {
            List<Integer> neighbors = new ArrayList<>();
            neighbors.add(dst);
            neighbors.add(weight);
            neighbors.put(src, neighbors);
        }
    }

    // Initialize a queue to store the nodes that need to be visited
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0); // start from node 0

    // Initialize a set to store the visited nodes
    Set<Integer> visited = new HashSet<>();
    visited.add(0);

    // Initialize a variable to store the minimum time required to collect all apples
    int minTime = 0;

    // Loop until all apples are collected or the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node and its neighbors
        int node = queue.poll();
        List<Integer> neighbors = neighbors.get(node);

        // If the current node has an apple and it has not been visited before, mark it as visited and increment the minimum time
        if (hasApple[node] && !visited.contains(node)) {
            visited.add(node);
            minTime++;
        }

        // Enqueue the neighbors of the current node
        for (int neighbor : neighbors) {
            queue.offer(neighbor);
        }
    }

    // Return the minimum time required to collect all apples
    return minTime;
}

