public String sortString(String s) {
    // Edge case: Empty string
    if (s.isEmpty()) {
        return s;
    }

    // Create a variable to store the result
    String result = "";

    // Create a variable to store the last character appended to the result
    char lastAppendedCharacter = '\u0000';

    // While there are still characters in the string
    while (!s.isEmpty()) {
        // Find the smallest character in the string that is greater than the last appended character
        int smallestGreaterCharacterIndex = -1;
        char smallestGreaterCharacter = '\u0000';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c > lastAppendedCharacter && (smallestGreaterCharacterIndex == -1 || c < smallestGreaterCharacter)) {
                smallestGreaterCharacterIndex = i;
                smallestGreaterCharacter = c;
            }
        }

        // Add the smallest greater character to the result
        result += smallestGreaterCharacter;
        lastAppendedCharacter = smallestGreaterCharacter;

        // Find the largest character in the string that is smaller than the last appended character
        int largestSmallerCharacterIndex = -1;
        char largestSmallerCharacter = '\u0000';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < lastAppendedCharacter && (largestSmallerCharacterIndex == -1 || c > largestSmallerCharacter)) {
                largestSmallerCharacterIndex = i;
                largestSmallerCharacter = c;
            }
        }

        // Add the largest smaller character to the result
        result += largestSmallerCharacter;
        lastAppendedCharacter = largestSmallerCharacter;
    }

    // Return the result
    return result;
}

public String sortString(String s) {

