    // Array to store the indices of the characters in the string.
    int[] indices = new int[chars.length];

    // Initialize the indices array with 0.
    Arrays.fill(indices, 0);

    // The first iteration of the loop will add the smallest character to the result.
    // We use the flag variable to keep track if we have already added the smallest character.
    boolean addedSmallest = false;

    // The second iteration of the loop will add the next smallest character to the result.
    // We use the flag variable to keep track if we have already added the next smallest character.
    boolean addedNextSmallest = false;

    // The third iteration of the loop will add the largest character to the result.
    // We use the flag variable to keep track if we have already added the largest character.
    boolean addedLargest = false;

    // The fourth iteration of the loop will add the next largest character to the result.
    // We use the flag variable to keep track if we have already added the next largest character.
    boolean addedNextLargest = false;

    // Loop until we have added all characters to the result.
    while (result.length() < s.length()) {

        // Iterate over the characters in the string.
        for (int i = 0; i < chars.length; i++) {

            // Check if the current character is the smallest character and we have not already added it.
            if (chars[i] == getSmallest(chars, indices)) {

                // Add the current character to the result.
                addCharacter(result, chars[i]);
                addedSmallest = true;

                // If the current character is the smallest character, we need to skip it in the next iteration.
                indices[i]++;

                break;
            }
        }

        // If we have already added the smallest character, we need to check if there is another smallest character.
        if (addedSmallest) {

            // Iterate over the characters in the string.
            for (int i = 0; i < chars.length; i++) {

                // Check if the current character is the next smallest character and we have not already added it.
                if (chars[i] == getNextSmallest(chars, indices)) {

                    // Add the current character to the result.
                    addCharacter(result, chars[i]);
                    addedNextSmallest = true;

                    // If the current character is the next smallest character, we need to skip it in the next iteration.
                    indices[i]++;

                    break;
                }
            }
        }

        // If we have already added the smallest and next smallest characters, we need to check if there is another largest character.
        if (addedSmallest && addedNextSmallest) {

            // Iterate over the characters in the string.
            for (int i = 0; i < chars.length; i++) {

                // Check if the current character is the largest character and we have not already added it.
                if (chars[i] == getLargest(chars, indices)) {

                    // Add the current character to the result.
                    addCharacter(result, chars[i]);
                    addedLargest = true;

                    // If the current character is the largest character, we need to skip it in the next iteration.
                    indices[i]++;

                    break;
                }
            }
        }

        // If we have already added the smallest, next smallest, and largest characters, we need to check if there is another largest character.
        if (addedSmallest && addedNextSmallest && addedLargest) {

            // Iterate over the characters in the string.
            for (int i = 0; i < chars.length; i++) {

                // Check if the current character is the next largest character and we have not already added it.
                if (chars[i] == getNextLargest(chars, indices)) {

                    // Add the current character to the result.
                    addCharacter(result, chars[i]);
                    addedNextLargest = true;

                    // If the current character is the next largest character, we need to skip it in the next iteration.
                    indices[i]++;

                    break;
                }
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    // Handle null or empty input
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Initialize result string with first character
    String result = s.charAt(0) + "";

    // Iterate over the rest of the characters in s
    for (int i = 1; i < s.length(); i++) {
        // Find the smallest character in s that is greater than the last appended character
        char smallestGreater = Character.MAX_VALUE;
        for (int j = i; j < s.length(); j++) {
            if (s.charAt(j) > result.charAt(result.length() - 1) && s.charAt(j) < smallestGreater) {
                smallestGreater = s.charAt(j);
            }
        }

        // If the character was found, append it to the result
        if (smallestGreater != Character.MAX_VALUE) {
            result += smallestGreater;
        }

        // Find the largest character in s that is smaller than the last appended character
        char largestSmaller = Character.MIN_VALUE;
        for (int j = i; j < s.length(); j++) {
            if (s.charAt(j) < result.charAt(result.length() - 1) && s.charAt(j) > largestSmaller) {
                largestSmaller = s.charAt(j);
            }
        }

        // If the character was found, append it to the result
        if (largestSmaller != Character.MIN_VALUE) {
            result += largestSmaller;
        }
    }

    return result;
}

public String sortString(String s) {
String result = "";
// Step 1
int i = 0;
while (i < s.length()) {
char smallest = s.charAt(i);
result += smallest;
i++;
}
// Step 2
int j = 1;
while (j < s.length()) {
char prevChar = result.charAt(result.length() - 1);
char smallestGreaterThanPrev = s.charAt(j);
while (smallestGreaterThanPrev <= prevChar) {
j++;
if (j == s.length()) {
break;
}
smallestGreaterThanPrev = s.charAt(j);
}
if (j == s.length()) {
break;
}
result += smallestGreaterThanPrev;
j++;
}
// Step 3
int k = s.length() - 2;
while (k >= 0) {
char prevChar = result.charAt(result.length() - 1);
char largestSmallerThanPrev = s.charAt(k);
while (largestSmallerThanPrev >= prevChar) {
k--;
if (k < 0) {
break;
}
largestSmallerThanPrev = s.charAt(k);
}
if (k < 0) {
break;
}
result = largestSmallerThanPrev + result;
k--;
}
return result;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of all elements in the array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array
    double average = (double) sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false;
    }

    // Split the array into two parts
    int[] part1 = new int[nums.length / 2];
    int[] part2 = new int[nums.length / 2];

    // Fill the first half of part1 with the elements from nums
    int index = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        part1[i] = nums[index];
        index++;
    }

    // Fill the second half of part2 with the elements from nums
    for (int i = nums.length / 2; i < nums.length; i++) {
        part2[i - nums.length / 2] = nums[index];
        index++;
    }

    // Calculate the sum of the first half of part1 and the second half of part2
    int sum1 = 0;
    int sum2 = 0;
    for (int i = 0; i < part1.length; i++) {
        sum1 += part1[i];
    }
    for (int i = 0; i < part2.length; i++) {
        sum2 += part2[i];
    }

    // Check if the sums are equal
    return sum1 == sum2;
}

