    }

    // Calculate the average of the input array
    double average = (double) sum / nums.length;

    // Loop through the input array and find the first index where the sum of the elements before it is equal to the average
    for (int i = 0; i < nums.length; i++) {
        int sumBefore = 0;
        for (int j = 0; j < i; j++) {
            sumBefore += nums[j];
        }
        if (sumBefore == average) {
            // If the sum is equal to the average, then return true
            return true;
        }
    }

    // If no such index is found, then return false
    return false;
}

