    }

    int average = sum / nums.length;
    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
    }

    if (leftSum == average) {
        return true;
    }

    int rightSum = sum - leftSum;
    if (rightSum == average) {
        return true;
    }

    return false;
}

