    int average = sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false; // Cannot split the array with a non-integer average
    }

    // Get the left and right subarrays
    int[] left = new int[nums.length / 2];
    int[] right = new int[nums.length / 2];
    for (int i = 0; i < nums.length; i++) {
        if (i < nums.length / 2) {
            left[i] = nums[i];
        } else {
            right[i - nums.length / 2] = nums[i];
        }
    }

    // Check if the left and right subarrays have the same average
    int leftSum = 0;
    int rightSum = 0;
    for (int num : left) {
        leftSum += num;
    }
    for (int num : right) {
        rightSum += num;
    }
    if (leftSum / left.length == rightSum / right.length) {
        return true;
    } else {
        return false;
    }
}

public int minCostClimbingStairs(int[] cost) {
   if (cost == null || cost.length == 0) {
     throw new IllegalArgumentException("Invalid input");
   }

   int[] dp = new int[cost.length + 1];
   dp[0] = 0;
   dp[1] = 0;

   for (int i = 2; i <= cost.length; i++) {
     dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
   }

   return Math.min(dp[cost.length], dp[cost.length - 1]);
}

public int minCostClimbingStairs(int[] cost) {
    int cost0 = Integer.MAX_VALUE;
    int cost1 = Integer.MAX_VALUE;
    for (int i = 0; i < cost.length; i++) {
        if (i == 0) {
            cost0 = cost[i];
        } else if (i == 1) {
            cost1 = cost[i];
        } else {
            cost0 = Math.min(cost0, cost[i - 1]);
            cost1 = Math.min(cost1, cost[i - 2]);
        }
    }
    return Math.min(cost0, cost1);
}

public int minCostClimbingStairs(int[] cost) {
  if (cost.length == 0) {
    throw new IllegalArgumentException("cost array cannot be empty");
  }

  int[] dp = new int[cost.length];
  dp[0] = cost[0];
  dp[1] = cost[1];

  for (int i = 2; i < cost.length; i++) {
    dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
  }

  return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
int minCost = 0;
int currentCost = 0;
for (int i = 0; i < cost.length; i++) {
if (minCost != 0) {
currentCost = (int) Math.min(Math.min(minCost, currentCost), cost[i]);
} else {
currentCost = cost[i];
}
minCost = currentCost;
}
return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    for (int i = 1; i < cost.length; i++) {
        int newCost = cost[i] + Math.min(minCostClimbingStairs(cost, i - 1), minCostClimbingStairs(cost, i - 2));
        minCost = Math.min(minCost, newCost);
    }
    return minCost;
}

