public boolean hasAllCodes(String s, int k) {
  // Check if the input string is null or empty
  if (s == null || s.isEmpty()) {
    return false;
  }

  // Check if the input k is valid
  if (k < 1) {
    return false;
  }

  // Create a substring array of size k
  String[] substrings = new String[k];

  // Loop through the input string and extract substrings of length k
  for (int i = 0; i < s.length() - k + 1; i++) {
    substrings[i] = s.substring(i, i + k);
  }

  // Check if all substrings of length k are present in the input string
  for (String substring : substrings) {
    if (!s.contains(substring)) {
      return false;
    }
  }

  return true;
}

public static boolean hasAllCodes(String s, int k) {
    // Check if the input string is empty or the length of the string is not divisible by k
    if (s.isEmpty() || s.length() % k != 0) {
      return false;
    }

    // Create a hash set to store all the binary strings of length k
    Set<String> binaryStrings = new HashSet<>();

    // Iterate through the input string and extract all the substrings of length k
    for (int i = 0; i < s.length(); i += k) {
      binaryStrings.add(s.substring(i, i + k));
