public int maxUniqueSplit(String s) {

	// Apply a sliding window technique to find the maximum number of unique substrings
	int maxUniques = 0;
	for (int i = 0; i < s.length(); i++) {
		// Find the rightmost character in the substring
		int rightMost = i;
		while (rightMost < s.length() && s.charAt(rightMost) == s.charAt(i)) {
			rightMost++;
		}

		// Find the leftmost character in the substring
		int leftMost = rightMost - 1;
		while (leftMost >= 0 && s.charAt(leftMost) == s.charAt(i)) {
			leftMost--;
		}

		// Calculate the length of the substring
		int length = rightMost - leftMost;

		// Update the maximum number of unique substrings
		maxUniques = Math.max(maxUniques, length * (length + 1) / 2);
	}

	return maxUniques;
}

