public int maxUniqueSplit(String s) {
    // Find the longest substring that ends at each position in the string
    int[] longestSubstring = new int[s.length()];
    for (int i = 0; i < s.length(); i++) {
        int j = i;
        while (j < s.length() && s.charAt(i) == s.charAt(j)) {
            j++;
        }
        longestSubstring[i] = j - i;
    }

    // Find the maximum number of unique substrings
    int maxUnique = 0;
    for (int i = 0; i < s.length(); i++) {
        int numUnique = 0;
        for (int j = i; j < s.length(); j += longestSubstring[j]) {
            if (s.substring(i, j + 1).contains(s.substring(j + 1, i))) {
                break;
            }
            numUnique++;
        }
        maxUnique = Math.max(maxUnique, numUnique);
    }

    return maxUnique;
}

