public int minOperations(String[] logs) {
    int steps = 0;
    Stack<String> folderStack = new Stack<>();

    for (String log : logs) {
        if (log.equals("../")) {
            if (folderStack.isEmpty()) {
                throw new IllegalArgumentException("Cannot perform ../ outside of a folder");
            }
