public String getSmallestString(int n, int k) {
   if (n < 1 || k < 1) {
       throw new IllegalArgumentException("n and k must be positive");
   }

   // Create a character array to store the string
   char[] chars = new char[n];

   // Initialize the character array with the smallest characters
   for (int i = 0; i < n; i++) {
       chars[i] = (char) ('a' + i);
   }

   // Sort the character array in ascending order
   Arrays.sort(chars);

   // Calculate the sum of the positions of the characters in the alphabet
   int sum = 0;
   for (int i = 0; i < n; i++) {
       sum += (int) chars[i] - (int) 'a' + 1;
   }

   // Check if the sum is equal to k
   if (sum == k) {
       return new String(chars);
   }

   // If the sum is not equal to k, then we need to add more characters
   // to the string to reach the target value of k
   while (sum != k) {
       // Find the next character that needs to be added
       int diff = k - sum;
       char c = (char) ('a' + diff - 1);

       // Add the character to the end of the string
       chars[n] = c;
       sum += diff;
   }

   return new String(chars);
}

