public static int longestLine(int[][] mat) {
    // Check argument
    if (mat == null) {
        throw new NullPointerException("The matrix is null");
    }
    // Initialize variables
    int maxLength = 0;
    int currentLength = 0;
    int row = mat.length;
    int col = mat[0].length;

    // Iterate through the matrix rows
    for (int i = 0; i < row; i++) {
        // Reset currentLength for each row
        currentLength = 0;
        // Iterate through the matrix columns
        for (int j = 0; j < col; j++) {
            // Check if the current element is 1
            if (mat[i][j] == 1) {
                // Increment the length of the current line
                currentLength++;
            } else {
                // If the current element is not 1, check if the current length is greater than the maximum length
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }
                // Reset the current length
                currentLength = 0;
            }
        }
        // Check if the last row is not a newline
        if (i < row - 1) {
            // If the last row is not a newline, check if the current length is greater than the maximum length
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
        }
    }
    // Return the maximum length
    return maxLength;
}

