    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                int direction = 0; // 0 for horizontal, 1 for vertical, 2 for diagonal, -1 for anti-diagonal
                while (i + direction >= 0 && i + direction < m && j - direction >= 0 && j - direction < n) {
                    if (mat[i + direction][j - direction] == 1) {
                        length++;
                        direction++;
                    } else {
                        break;
                    }
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

