    // Iterate through each row of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Iterate through each column of the matrix
        for (int j = 0; j < mat[i].length; j++) {
            // Check if the current position is a 1
            if (mat[i][j] == 1) {
                // If the current position is a 1, check if it is the start of a new line
                if (longestLineLength == 0) {
                    // If it is the start of a new line, set the direction of the line and the length to 1
                    longestLineDirection = 1;
                    longestLineLength = 1;
                } else {
                    // If it is not the start of a new line, check if it is a horizontal, vertical, diagonal, or anti-diagonal line
                    if (longestLineDirection == 1) {
                        // If it is a horizontal line, increment the length by 1
                        longestLineLength++;
                    } else if (longestLineDirection == 2) {
                        // If it is a vertical line, decrement the length by 1
                        longestLineLength--;
                    } else if (longestLineDirection == 3) {
                        // If it is a diagonal line, increment the length by 1
                        longestLineLength++;
                    } else {
                        // If it is an anti-diagonal line, decrement the length by 1
                        longestLineLength--;
                    }
                }
            }
        }
    }

    // Return the longest line length
    return longestLineLength;
}

