        int sum = A[i] + A[i + 1];
        // check if the sum is a perfect square
        if (sum % Math.sqrt(sum) == 0) {
            // if it is a perfect square, increment the count for the current element
            count[A[i]]++;
        }
    }

    // calculate the number of square permutations
    int numSquarePermutations = 0;
    for (int c : count) {
