    Arrays.sort(A);

    // Initialize variables to keep track of permutations and squares
    int numPermutations = 1;
    int numSquares = 0;

    // Iterate over the sorted array
    for (int i = 0; i < A.length - 1; i++) {
        // If the sum of the current element and the next element is a perfect square,
        // then the current element is a square, and we can update the number of squares
        if (isPerfectSquare(A[i] + A[i + 1])) {
            numSquares++;
        }

        // Update the number of permutations based on the number of squares
        numPermutations *= numSquares + 1;
    }

    // Return the number of square permutations
    return numPermutations;
