public static int squarePermutations(int[] A) {
    // HashSet to keep track of the permutations we've seen
    Set<String> seenPermutations = new HashSet<>();
    // Sort the array in non-decreasing order
    Arrays.sort(A);
    // Initial permutation
    String initialPermutation = permutation(A);
    seenPermutations.add(initialPermutation);
    // Loop through each pair of adjacent elements in the array
    for (int i = 0; i < A.length - 1; i++) {
        // If the sum of the pair is a perfect square
        if (Math.sqrt(A[i] + A[i + 1]) % 1 == 0) {
            // Swap the adjacent elements
            A[i] ^= A[i + 1];
            A[i + 1] ^= A[i];
            A[i] ^= A[i + 1];
            // Get the new permutation
            String newPermutation = permutation(A);
            // If the new permutation is not seen before, add it to the set
            if (!seenPermutations.contains(newPermutation)) {
                seenPermutations.add(newPermutation);
            }
        }
    }
    // Return the size of the set, which is the number of square permutations
    return seenPermutations.size();
}

