        while (left > 0 && heights[left] >= heights[left - 1]) {
            left--;
        }
        int right = i;
        while (right < heights.length - 1 && heights[right] >= heights[right + 1]) {
            right++;
        }
        maxArea = Math.max(maxArea, (right - left + 1) * heights[i]);
        i = right;
    }
    return maxArea;
}

