    return -1;
  }

  int[] digits = new int[n.toString().length()];
  Arrays.fill(digits, 0);

  for (int i = 0; i < n.toString().length(); i++) {
    digits[i] = n % 10;
    n = n / 10;
  }

  Arrays.sort(digits);

  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < digits.length; i++) {
    sb.append(digits[i]);
  }

