public static int findSmallestInteger(int n) {
    int[] digits = new int[10];
    int lastDigit = 0;
    for (int i = 0; i < n; i++) {
        lastDigit = n % 10;
        digits[lastDigit]++;
        n /= 10;
    }

    int smallestInteger = 0;
    for (int i = 9; i > 0; i--) {
        if (digits[i] > 0) {
            smallestInteger *= 10;
            smallestInteger += i;
            digits[i]--;
        }
    }
    if (smallestInteger > n) {
        return smallestInteger;
    } else {
        return -1;
    }
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    for (int i = n; i > 0; i--) {
        int num = i;
        int[] digits = new int[10];
        while (num > 0) {
            digits[num % 10]++;
            num /= 10;
        }
        Arrays.sort(digits);
        int newNum = 0;
        for (int digit : digits) {
            newNum = newNum * 10 + digit;
        }
        if (newNum > n && (smallest == -1 || newNum < smallest)) {
            smallest = newNum;
        }
    }
    return smallest;
}

