public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    int det = (x1 - x2) * (y1 - y3) - (x1 - x3) * (y1 - y2);

    return det != 0;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the number of points is 3
    if (points.length != 3) {
        throw new IllegalArgumentException("Input should be an array of 3 points");
    }

    // Get the differences between the points
    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    // Check if the differences between the points form a right angle
    if (dx1 * dy2 != dy1 * dx2) {
        throw new IllegalArgumentException("Input points do not form a right angle");
    }

    // Check if the product of the differences is negative
    if (dx1 * dx2 < 0 || dy1 * dy2 < 0) {
        throw new IllegalArgumentException("Input points do not form a boomerang");
    }

    return true;
}

