    if (points.length < 3) {
        return false;
    }

    // Sort the points based on the x-coordinate
    Arrays.sort(points, (a, b) -> Integer.compare(a[0], b[0]));

    // Check if the first and last points are the same
    if (points[0][0] == points[points.length - 1][0] && points[0][1] == points[points.length - 1][1]) {
        return false;
    }

    // Check if the second last point is not between the first and last points
    if (points[points.length - 2][0] >= points[0][0] && points[points.length - 2][0] <= points[points.length - 1][0] &&
            points[points.length - 2][1] >= points[0][1] && points[points.length - 2][1] <= points[points.length - 1][1]) {
        return false;
    }

    return true;
}

public static boolean isBoomerang(int[][] points) {
  // Check if the number of points is 3
  if (points.length != 3) {
    return false;
  }

  // Calculate the squared distances between the points
  int[] distances = new int[3];
  for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
      if (i != j) {
        distances[i] += (points[i][0] - points[j][0]) * (points[i][0] - points[j][0]);
        distances[i] += (points[i][1] - points[j][1]) * (points[i][1] - points[j][1]);
      }
    }
  }

  // Check if the distances are all the same
  for (int i = 0; i < 3; i++) {
    if (distances[i] != distances[0]) {
      return false;
    }
  }

  // Return true if the distances are all the same
  return true;
}

public static int findNthUglyNumber(int n) {
    int[] dp = new int[n + 1];
    dp[1] = 1;
    int p2 = 1, p3 = 1, p5 = 1;
    for (int i = 2; i <= n; i++) {
        int min = Math.min(dp[p2] * 2, Math.min(dp[p3] * 3, dp[p5] * 5));
        dp[i] = min;
        if (min == dp[p2] * 2) {
            p2++;
        }
        if (min == dp[p3] * 3) {
            p3++;
        }
        if (min == dp[p5] * 5) {
            p5++;
        }
    }
    return dp[n];
}

