public static int findNthUglyNumber(int n) { 
    if (n < 1) { 
      throw new IllegalArgumentException("n must be positive"); 
    } 

    int[] primeFactors = {2, 3, 5}; 
    int[] factors = new int[n]; 
    factors[0] = 1; 
    for (int i = 1; i < n; i++) { 
      for (int p = 0; p < primeFactors.length; p++) { 
        int factor = factors[i - 1] * primeFactors[p]; 
        if (factor > 0 && factor < factors.length) { 
          factors[i] = factor; 
          break; 
        } 
      }  
      if (factors[i] < 1) { 
        throw new IllegalStateException("No more ugly numbers"); 
      } 
    } 
    return factors[n - 1]; 
  }

