    dp[1] = 1;

    int multiply = 1;

    for (int i = 2; i <= n; i++) {
        dp[i] = multiply;
        if (dp[i] == dp[i - 1]) {
            multiply++;
        }
        if (dp[i] == dp[i - 2]) {
            multiply++;
        }
        if (dp[i] == dp[i - 3]) {
            multiply++;
        }
    }

    return dp[n];
}

