        result.add(i);

        // If the current number is a two-digit number, we need to
        // continue iterating to find the next number
        if (i > 9) {
            int nextNumber = i + 1;
            while (nextNumber <= n) {
                result.add(nextNumber);
                nextNumber += 1;
            }
        }
    }

    return result;
}

