            // If i is a perfect square, increment the count of perfect square numbers
            // that we've seen so far
            squareCounts.put(i, squareCounts.getOrDefault(i, 0) + 1);
        }
    }

    // Loop through the hash table and find the minimum number of perfect square numbers
    // that can be used to sum up to n
    for (int square : squareCounts.keySet()) {
        int count = squareCounts.get(square);
        if (n - square * count < 0) {
            // If the number of perfect square numbers that we've seen so far
            // is greater than the number of remaining integers that need to be
            // summed up to n, we can't use these perfect square numbers to sum up to n
            continue;
        }
        minSquares = Math.max(minSquares, count);
    }

    return minSquares;
}

public static String reverseWords(String s) {
   String[] words = s.split(" ");
   String result = "";

   for (int i = 0; i < words.length; i++) {
      String word = words[i];
      StringBuilder reversedWord = new StringBuilder(word);
      reversedWord.reverse();
      result += reversedWord.toString() + " ";
   }

   return result.trim();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    String[] words = s.split(" ");
    StringBuilder reversedWords = new StringBuilder();

    for (String word : words) {
        reversedWords.append(new StringBuffer(word).reverse().toString());
        reversedWords.append(" ");
    }

    return reversedWords.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
       sb.append(new StringBuilder(word).reverse().toString()).append(" ");
    }
    return sb.toString().trim();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        char[] chars = word.toCharArray();
        Arrays.reverse(chars);
        sb.append(new String(chars));
        if (i != words.length - 1) {
            sb.append(" ");
        }
    }
    return sb.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    String result = "";

    for (String word : words) {
        String reversedWord = "";
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord += word.charAt(i);
        }
        result += reversedWord + " ";
    }

    return result.trim();
}
